<?php $ubah=$row!==NULL;$v=function($k,$def='')use($row,$old){if(!empty($old)&&array_key_exists($k,$old))return(string)$old[$k];if($row&&array_key_exists($k,$row)&&$row[$k]!==NULL)return(string)$row[$k];return$def;};?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo $ubah?'Ubah':'Tambah';?> Aturan — SIP Gatutkaca</title><link rel="icon" type="image/png" href="<?php echo base_url('assets/img/icon.png'); ?>"><link href="https://fonts.googleapis.com/css2?family=Marcellus&family=Plus+Jakarta+Sans:wght@300;400;500;600&display=swap" rel="stylesheet"><style>
:root{--gold:#A57E2C;--display:'Marcellus',serif;--body:'Plus Jakarta Sans',sans-serif;--bg:#FDFBF5;--text:#152A3B;--muted:#64798b;--line:#d7e1e6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:300 14px/1.7 var(--body)}a{text-decoration:none;color:inherit}.top{height:84px;display:flex;align-items:center;justify-content:space-between;padding:0 34px;border-bottom:1px solid var(--line);background:#fff}.brand{font:400 19px var(--display);letter-spacing:.14em;color:var(--gold)}.wrap{max-width:900px;margin:0 auto;padding:52px 28px}.eyebrow{margin:0;color:var(--gold);font-size:11px;letter-spacing:.34em;text-transform:uppercase}h1{margin:8px 0 10px;font:400 40px var(--display)}.lead{color:var(--muted)}.notice{margin:22px 0;padding:14px 18px;border:1px solid #e0526b;background:#fff1f3;color:#bd3048}.grid{display:grid;grid-template-columns:180px 1fr;gap:22px;margin-top:34px;padding:30px;background:#fff;border:1px solid var(--line)}.field.full{grid-column:1/-1}.field label{display:block;margin-bottom:7px;color:var(--gold);font-size:10px;font-weight:600;letter-spacing:.14em;text-transform:uppercase}.field input[type=text],.field input[type=number],.field textarea{width:100%;padding:12px 14px;border:1px solid var(--line);background:#fff;color:var(--text);font:400 14px var(--body)}.field textarea{min-height:130px;resize:vertical}.check{display:flex;align-items:center;gap:10px}.hint{margin:7px 0 0;color:var(--muted);font-size:11px}.current{margin-top:10px;padding:12px;background:#f3f7f8}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}.btn{padding:12px 20px;border:1px solid var(--line);background:#fff;color:var(--text);font:600 10px var(--body);letter-spacing:.14em;text-transform:uppercase;cursor:pointer}.btn.gold{background:#C9A24B;border-color:#C9A24B}@media(max-width:650px){.grid{grid-template-columns:1fr;padding:22px}.top{padding:0 18px}h1{font-size:32px}}
</style></head><body><header class="top"><a class="brand" href="<?php echo base_url(); ?>">SIP GATUTKACA</a><a class="btn" href="<?php echo base_url('admin/aturan'); ?>">← Kembali</a></header><main class="wrap"><p class="eyebrow">Panel Admin</p><h1><?php echo $ubah?'Ubah Aturan':'Tambah Aturan';?></h1><p class="lead">PDF bersifat opsional dan dapat diunggah kemudian. Ukuran maksimum 20 MB.</p><?php if(!empty($error)):?><div class="notice"><?php echo htmlspecialchars($error,ENT_QUOTES,'UTF-8');?></div><?php endif;?>
<form method="post" enctype="multipart/form-data" action="<?php echo base_url('admin/aturan-simpan'.($ubah?'/'.(int)$row['id']:''));?>"><div class="grid"><div class="field full"><label for="judul">Judul Aturan *</label><textarea id="judul" name="judul" required><?php echo htmlspecialchars($v('judul'),ENT_QUOTES,'UTF-8');?></textarea></div><div class="field"><label>ID</label><input type="text" readonly value="<?php echo $ubah?(int)$row['id']:'Dibuat otomatis saat disimpan';?>"><p class="hint">ID dibuat otomatis oleh database dan tidak dapat diubah.</p></div><div class="field"><label>Status Publikasi</label><label class="check"><input type="checkbox" name="aktif" value="1" <?php echo $v('aktif','1')==='1'?'checked':'';?>> Tampilkan di halaman publik</label></div><div class="field full"><label for="pdf">Dokumen PDF</label><input id="pdf" type="file" name="file_pdf" accept="application/pdf,.pdf"><p class="hint">Hanya PDF, maksimal 20 MB. Unggahan baru akan mengganti PDF lama.</p><?php if($ubah&&!empty($row['file_pdf'])):?><div class="current"><a href="<?php echo base_url('regulasi/unduh/'.(int)$row['id']);?>">Lihat PDF saat ini</a><label class="check" style="margin-top:8px"><input type="checkbox" name="hapus_pdf" value="1"> Hapus PDF saat disimpan</label></div><?php endif;?></div></div><div class="buttons"><button class="btn gold" type="submit">Simpan Aturan</button><a class="btn" href="<?php echo base_url('admin/aturan');?>">Batal</a></div></form></main></body></html>
